"""Compare the artifacts regenerated by run_pipeline.py against the FROZEN outputs (read-only).

Per artifact: SHA-256 equality first; if the bytes differ, numeric equality with the stated tolerance
(CSV) or structural equality (JSON). Every file is reported as MATCH or DIFFER with a detail string.
Writes <out>/reproducibility_comparison.{csv,md}. Never writes into a frozen directory.
"""
from __future__ import annotations

import json
import pickle
import sys
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from canary_sim import versioning as VR  # noqa: E402

SPLITS = ("train", "val", "test", "shifted_test", "stress", "broad_basin")


def _cmp_csv_numeric(a: Path, b: Path, rtol: float, atol: float) -> tuple[bool, str]:
    da, db = pd.read_csv(a, low_memory=False), pd.read_csv(b, low_memory=False)
    if list(da.columns) != list(db.columns):
        return False, f"columns differ ({len(da.columns)} vs {len(db.columns)})"
    if da.shape != db.shape:
        return False, f"shape differs {da.shape} vs {db.shape}"
    worst = 0.0
    for c in da.columns:
        if pd.api.types.is_numeric_dtype(da[c]) and pd.api.types.is_numeric_dtype(db[c]):
            x, y = da[c].to_numpy(dtype=float), db[c].to_numpy(dtype=float)
            if not np.allclose(x, y, rtol=rtol, atol=atol, equal_nan=True):
                d = np.nanmax(np.abs(x - y))
                return False, f"column {c} differs (max abs diff {d:.3g})"
            worst = max(worst, float(np.nanmax(np.abs(x - y))) if len(x) else 0.0)
        elif not da[c].astype(str).equals(db[c].astype(str)):
            return False, f"column {c} differs (non-numeric)"
    return True, f"numeric equality within rtol={rtol:g}, atol={atol:g}; max abs diff {worst:.3g}"


def compare_file(new: Path, frozen: Path, rtol: float, atol: float) -> tuple[str, str]:
    if not new.exists():
        return "DIFFER", f"pipeline file missing: {new}"
    if not frozen.exists():
        return "DIFFER", f"frozen file missing: {frozen}"
    if VR.sha256_file(new) == VR.sha256_file(frozen):
        return "MATCH", "sha256 identical"
    if new.suffix == ".csv":
        ok, msg = _cmp_csv_numeric(new, frozen, rtol, atol)
        return ("MATCH" if ok else "DIFFER"), ("bytes differ; " + msg)
    if new.suffix == ".json":
        try:
            ok = json.loads(new.read_text(encoding="utf-8")) == json.loads(frozen.read_text(encoding="utf-8"))
        except Exception as e:  # pragma: no cover
            return "DIFFER", f"json parse error {e}"
        return ("MATCH" if ok else "DIFFER"), ("bytes differ; json structurally " + ("equal" if ok else "different"))
    return "DIFFER", "bytes differ"


def run_comparison(pcfg: dict, out: Path, root: Path = ROOT) -> pd.DataFrame:
    tol = pcfg.get("numeric_tolerance", {"rtol": 1e-9, "atol": 1e-12})
    rtol, atol = float(tol["rtol"]), float(tol["atol"])
    fz = {k: (root / v) for k, v in pcfg["frozen"].items()}
    rows = []

    def add(artifact, frozen, status, detail):
        rows.append({"artifact": artifact, "frozen_reference": str(frozen), "status": status, "detail": detail})

    # 1. dataset tables vs frozen outputs/datasets_v3 (v3 feature set)
    d_new = out / "datasets"
    names = ["manifest.csv", "window_labels.csv", "window_features.csv", "runs_metadata.json"]
    names += [f"features_{s}.csv" for s in SPLITS] + [f"labels_{s}.csv" for s in SPLITS]
    for n in names:
        st, dt = compare_file(d_new / n, fz["datasets_v3"] / n, rtol, atol)
        add(f"datasets/{n}", fz["datasets_v3"] / n, st, dt)
    # 1b. manifest + labels vs the original frozen outputs/datasets (v1 feature set differs, labels must not)
    for n in ("manifest.csv", "window_labels.csv"):
        st, dt = compare_file(d_new / n, fz["datasets"] / n, rtol, atol)
        add(f"datasets/{n} (vs outputs/datasets)", fz["datasets"] / n, st, dt)
    add("datasets/metadata.json", fz["datasets_v3"] / "metadata.json", "N/A",
        "frozen datasets_v3 predates dataset versioning (no metadata.json); new file, verified by verify_dataset.py")

    # 2. reference state timeline + telemetry (reference run seed 20260001)
    rr = out / "reference_runs"
    fd = fz["faults_demo"]
    for n in ["state_timeline.csv", "metadata.json", "telemetry_clean.csv", "telemetry_clean_metadata.json",
              "telemetry_imu_drift.csv", "telemetry_imu_drift_metadata.json",
              "telemetry_hub_self_motion.csv", "telemetry_hub_self_motion_metadata.json"]:
        st, dt = compare_file(rr / "faults_demo" / "sim_gradual_20260001" / n, fd / n, rtol, atol)
        add(f"reference_runs/faults_demo/{n}", fd / n, st, dt)
    ro = fz["run_one"]
    for n in ["state_timeline.csv", "metadata.json", "window_features.csv"]:
        st, dt = compare_file(rr / "run_one" / "sim_gradual_20260001" / n, ro / n, rtol, atol)
        if n == "window_features.csv" and st == "DIFFER":
            dt += " [expected: frozen file predates the v3 feature-set extension of features.py]"
        add(f"reference_runs/run_one/{n}", ro / n, st, dt)

    # 3. models + operating points: identical predictions / thresholds on the frozen test features
    mp = out / "models"
    if (mp / "trained_models.pkl").exists():
        new_models = pickle.load(open(mp / "trained_models.pkl", "rb"))
        new_ops = pickle.load(open(mp / "operating_points.pkl", "rb"))
        fm = pickle.load(open(fz["eval_v3"] / "trained_models_v3.pkl", "rb"))
        fo = pickle.load(open(fz["eval_v3"] / "operating_points_v3.pkl", "rb"))
        test = pd.read_csv(fz["datasets_v3"] / "features_test.csv", low_memory=False)
        for name in ("threshold_rule", "logistic_regression", "random_forest"):
            same = bool(np.array_equal(new_models[name].predict(test), fm[name].predict(test)))
            add(f"models/{name} predictions on frozen test features", fz["eval_v3"] / "trained_models_v3.pkl",
                "MATCH" if same else "DIFFER", "identical window predictions" if same else "predictions differ")
        same = new_models["threshold_rule"].thresholds == fm["threshold_rule"].thresholds
        add("models/threshold_rule thresholds", fz["eval_v3"] / "trained_models_v3.pkl",
            "MATCH" if same else "DIFFER", "all 16 thresholds equal" if same else "thresholds differ")
        for key in ("episode_fa_le_1", "strict_window_fa_le_1"):
            for name in ("random_forest", "logistic_regression"):
                a, b = new_ops[key][name], fo[key][name]
                same = (a.group_thresholds == b.group_thresholds and a.k == b.k and a.m == b.m)
                add(f"operating_points/{key}/{name} (tau per group, k, m)", fz["eval_v3"] / "operating_points_v3.pkl",
                    "MATCH" if same else "DIFFER",
                    f"tau={a.group_thresholds}, k={a.k}, m={a.m}" if same else
                    f"new tau={a.group_thresholds} k={a.k} m={a.m} vs frozen tau={b.group_thresholds} k={b.k} m={b.m}")
        for fn, fzn in (("trained_models.pkl", "trained_models_v3.pkl"), ("operating_points.pkl", "operating_points_v3.pkl")):
            same = VR.sha256_file(mp / fn) == VR.sha256_file(fz["eval_v3"] / fzn)
            add(f"models/{fn} (raw pickle bytes)", fz["eval_v3"] / fzn, "MATCH" if same else "DIFFER",
                "sha256 identical" if same else "pickle bytes differ (informational; behaviour compared above)")

    # 4. headline metrics vs frozen eval_v3 (version == 'v3 (new features)')
    hm = out / "eval" / "headline_metrics.csv"
    if hm.exists():
        new = pd.read_csv(hm)
        fro = pd.read_csv(fz["eval_v3"] / "v2_vs_v3_all_snr_comparison.csv")
        fro = fro[fro["version"] == "v3 (new features)"]
        keys = ["split", "regime", "model"]
        cols = [c for c in new.columns if c not in keys + ["version"]]
        mg = new.merge(fro[keys + cols], on=keys, suffixes=("", "_frozen"), how="outer", indicator=True)
        n_total = len(mg)
        both = mg[mg["_merge"] == "both"]
        bad = []
        for _, r in both.iterrows():
            for c in cols:
                if not np.isclose(float(r[c]), float(r[c + "_frozen"]), rtol=rtol, atol=1e-9, equal_nan=True):
                    bad.append(f"{r['split']}/{r['model']}/{r['regime']}:{c} {r[c]} vs {r[c + '_frozen']}")
        only = n_total - len(both)
        status = "MATCH" if (not bad and only == 0) else "DIFFER"
        add("eval/headline_metrics.csv (all headline metrics, 5 splits x 3 models x 3 regimes)",
            fz["eval_v3"] / "v2_vs_v3_all_snr_comparison.csv", status,
            f"{len(both)} rows compared, {len(bad)} cell difference(s), {only} unmatched row(s)"
            + ("" if not bad else "; first: " + "; ".join(bad[:3])))

    df = pd.DataFrame(rows)
    df.to_csv(out / "reproducibility_comparison.csv", index=False)
    n_m, n_d = int((df["status"] == "MATCH").sum()), int((df["status"] == "DIFFER").sum())
    md = ["# Reproducibility comparison (pipeline output vs FROZEN outputs; SYNTHETIC / SIMULATION)", "",
          f"MATCH: {n_m}  |  DIFFER: {n_d}  |  N/A: {int((df['status'] == 'N/A').sum())}", "",
          "| artifact | status | detail |", "|---|---|---|"]
    for _, r in df.iterrows():
        md.append(f"| {r['artifact']} | {r['status']} | {r['detail']} |")
    (out / "reproducibility_comparison.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    print(f"[compare] MATCH={n_m} DIFFER={n_d}")
    return df


if __name__ == "__main__":
    import argparse
    import yaml
    ap = argparse.ArgumentParser()
    ap.add_argument("--config", default=str(ROOT / "configs" / "pipeline_v1.yaml"))
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    run_comparison(yaml.safe_load(open(a.config, encoding="utf-8")), Path(a.out))
